import json

# HYPOTHESIS: The output keeps background(0), preserves noise pattern(7,9) as is,
# BUT fills each object's bounding box with the OBJECT COLOR (solidify objects)
# This should create perfect rectangles for objects

object_colors = {3, 5, 6, 8}

def find_bbox(grid, target_val):
    bbox = None
    for r in range(20):
        for c in range(20):
            if grid[r][c] == target_val:
                if bbox is None:
                    bbox = (r, c, r, c)
                else:
                    bbox = (min(bbox[0], r), min(bbox[1], c), max(bbox[2], r), max(bbox[3], c))
    return bbox

bboxes = {}
for obj_color in object_colors:
    bbox = find_bbox(input_grid, obj_color)
    bboxes[obj_color] = bbox
    print(f"Color {obj_color}: bbox = {bbox}")

output_grid = [[0]*20 for _ in range(20)]
# Copy background/noise from input
for r in range(20):
    for c in range(20):
        val = input_grid[r][c]
        if val == 7 or val == 9:
            output_grid[r][c] = val
        else:
            output_grid[r][c] = 0

# Fill each object bbox with the object color
for obj_color, bbox in bboxes.items():
    if bbox:
        r_min, c_min, r_max, c_max = bbox
        for r in range(r_min, r_max + 1):
            for c in range(c_min, c_max + 1):
                output_grid[r][c] = obj_color

print("\nSolidify objects by filling their bboxes with object color:")
for i, row in enumerate(output_grid):
    print(f"{i}: {row}")
print()
print(json.dumps({"action": "submit", "grid": output_grid}))
